 array['Tim Kelly''s bright high-gain riff powers the glam-metal anthem','Strong presence and gain keep the chords cutting and aggressive'],
 array['Attack the riff with tight palm muting and firm down-strokes','Use pinch harmonics and bends for the glam-metal flourishes'],
 'Slaughter "Stick It to Ya"; Tim Kelly high-gain guitar into a Marshall-style amp.',68),
('heaven','warrant','guitar','intro','Clean Arpeggio Intro','clean','glam metal','clean','intermediate',
 'Fender Stratocaster','Fender Twin Reverb','2x12 Combo','Single-coil',
 '[]'::jsonb,'{"gain":2,"bass":5,"mids":5,"treble":6,"presence":5,"reverb":3,"delay":2,"master":6}'::jsonb,
 array['A clean arpeggiated figure opens the power ballad before the band enters','Bright single-coil tone with reverb keeps the picked notes clear'],
 array['Pick the arpeggios cleanly and let each note ring','Add reverb and light chorus for the spacious ballad intro'],
 'Warrant "Dirty Rotten Filthy Stinking Rich"; clean arpeggiated power-ballad intro into a clean amp.',66)
) as c(song_slug, artist_slug, mode, part_type, part_label, tone_type, genre, tone_category, difficulty,
       original_guitar, original_amp, original_cab, original_pickup,
       original_effects, original_settings, adaptation_notes, playing_notes, source_summary, confidence)
join public.artists a on a.slug = c.artist_slug
join public.songs s on s.artist_id = a.id and s.slug = c.song_slug
on conflict (song_id, mode, part_type, tone_type, part_label) do nothing;

do $$
declare
  expected int;
  actual int;
begin
  select count(*) into expected from phase_targets;
  -- Count DISTINCT target songs that received an admin_verified profile of ANY mode
  -- (a phase may legitimately contain both guitar and bass profiles).
  select count(*) into actual from (
    select distinct a.slug, s.slug
    from public.song_tone_profiles p
    join public.songs s on s.id = p.song_id
    join public.artists a on a.id = s.artist_id
    join phase_targets t on t.artist_slug = a.slug and t.song_slug = s.slug
    where p.verification_status = 'admin_verified'
  ) q;
  if actual < expected then
    raise exception 'POST-CONDITION FAILED: % target songs got a verified profile for % targets — slug mismatch between fragments', actual, expected;
  end if;
end $$;

commit;
